<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Compound Calculator Online','description'=>'Calculate compound growth from principal, rate, time and compounding frequency.','url'=>'https://smarttoolz.in/tools/compound-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Compound Calculator</h1><p>Calculate compound growth instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Principal<input id="p" type="number" value="10000"></label><label>Annual rate %<input id="r" type="number" value="8"></label><label>Years<input id="y" type="number" value="5"></label><label>Times per year<input id="n" type="number" value="12"></label><button id="go" class="tool-btn">Calculate</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let P=+p.value,r=+document.getElementById('r').value/100,n=+document.getElementById('n').value,y=+document.getElementById('y').value,A=P*Math.pow(1+r/n,n*y);o.textContent=`Final: ${A.toFixed(2)} · Interest: ${(A-P).toFixed(2)}`};go.click()</script><?php smarttoolz_tool_page_end(); ?>